function toggleAllTodos() {
  var next = toggleAll.checked;
  todos.forEach(function (t) { t.completed = next; });
  var lis = todoList.querySelectorAll('li');
  for (var i = 0; i < lis.length; i++) {
    var li = lis[i];
    var todo = todos.find(function (t) { return t.id === Number(li.dataset.id); });
    var done = todo ? todo.completed : next;
    li.classList.toggle('completed', done);
    var toggle = li.querySelector('.toggle');
    if (toggle) toggle.checked = done;
  }
  save();
  syncMeta();
}

